import React, { useEffect, useState } from "react";

export default function Hero() {
  // typing effect text list
  const roles = ["Full-Stack Developer", "UI Designer", "Problem Solver"];
  const [text, setText] = useState("");
  const [roleIndex, setRoleIndex] = useState(0);
  const [isDeleting, setIsDeleting] = useState(false);
  const [speed, setSpeed] = useState(120);

  useEffect(() => {
    let ticker = null;
    const currentRole = roles[roleIndex % roles.length];

    ticker = setTimeout(() => {
      if (!isDeleting) {
        // type
        setText(currentRole.substring(0, text.length + 1));
        setSpeed(120);
        if (text.length + 1 === currentRole.length) {
          // pause before deleting
          setTimeout(() => setIsDeleting(true), 900);
        }
      } else {
        // delete
        setText(currentRole.substring(0, text.length - 1));
        setSpeed(60);
        if (text.length - 1 === 0) {
          setIsDeleting(false);
          setRoleIndex((prev) => (prev + 1) % roles.length);
        }
      }
    }, speed);

    return () => clearTimeout(ticker);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [text, isDeleting, roleIndex]);

  // smooth scroll to projects section
  function handleViewProjects(e) {
    e.preventDefault();
    const el = document.getElementById("projects");
    if (el) el.scrollIntoView({ behavior: "smooth", block: "start" });
  }

  return (
    <section id="hero" className="hero-section d-flex align-items-center">
      <div className="container">
        <div className="row align-items-center gy-4">
          {/* Left text column */}
          <div className="col-lg-6">
            <div className="hero-left">
              <h1 className="hero-name">
                <span className="gradient-text">Alex Johnson</span>
              </h1>

              <h3 className="hero-role">
                <span className="typed-text">{text}</span>
                <span className="typed-cursor" aria-hidden="true"></span>
              </h3>

              <p className="hero-desc">
                Crafting exceptional digital experiences with clean code and
                thoughtful UI. I build scalable web apps and delightful design
                systems that solve real problems.
              </p>

              <div className="hero-ctas mt-4">
                <button className="btn btn-primary me-3" onClick={handleViewProjects}>
                  View Projects
                  <span className="btn-arrow"> →</span>
                </button>

                <a className="btn btn-outline-dark" href="/assets/CV.pdf" download>
                  Download CV
                </a>
              </div>
            </div>
          </div>

          {/* Right image column */}
          <div className="col-lg-6 text-center">
            <div className="hero-image-wrap">
              {/* Use /assets/hero-image.png (put file in public/assets/) or change path */}
              <img
                src="/assets/hero-image.png"
                alt="Workspace with monitors showing code"
                className="hero-image img-fluid"
              />
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}
